#!/usr/bin/env bash
set -u

# Audit original filtrado pelos IDs de baseline_rhel_light_resumido.csv.
# Lacunas e divergencias herdadas estao registradas no README.md.
# IDs 999+ sao utilitarios e nao participam da conformidade funcional.

run_item() {
  local id="$1" title="$2" severity="$3" cmd="$4" expect="$5"
  local output rc result
  output=$(bash -c "$cmd" 2>&1)
  rc=$?
  if printf '%s
' "$output" | grep -Pq -- "$expect"; then result=PASS; else result=FAIL; fi
  printf '%s,%s,%s,%s
' "$id" "$title" "$severity" "$result"
  if [ "${AUDIT_DEBUG:-0}" = 1 ]; then
    printf 'cmd: %s
expect: %s
rc: %s
output:
%s
' "$cmd" "$expect" "$rc" "$output" >&2
  fi
}

echo 'ID,NOME,CRITICIDADE,RESULTADO'
run_item 1 'Verifique se o módulo do kernel do CRAMFS não está disponível' Baixa '(modinfo cramfs &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+cramfs\b'"'"' && ! lsmod | grep -q cramfs) || (! modinfo cramfs &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 4 'Verifique se o módulo do kernel do HFS não está disponível' Baixa '(modinfo hfs &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+hfs\b'"'"' && ! lsmod | grep -q hfs) || (! modinfo hfs &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 5 'Verifique se o módulo do kernel do HFSPLUS não está disponível' Baixa '(modinfo hfsplus &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+hfsplus\b'"'"' && ! lsmod | grep -q hfsplus) || (! modinfo hfsplus &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 6 'Verifique se o módulo do kernel do JFFS2 não está disponível' Baixa '(modinfo jffs2 &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+jffs2\b'"'"' && ! lsmod | grep -q jffs2) || (! modinfo jffs2 &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 7 'Verifique se o módulo do kernel do FREEVXFS não está disponível' Baixa '(modinfo freevxfs &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+freevxfs\b'"'"' && ! lsmod | grep -q freevxfs) || (! modinfo freevxfs &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 10 'Verifique se o módulo do kernel do DCCP não está disponível' 'Média' '(modinfo dccp &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+dccp\b'"'"' && ! lsmod | grep -q dccp) || (! modinfo dccp &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 12 'Verifique se o módulo do kernel do RDS não está disponível' 'Média' '(modinfo rds &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+rds\b'"'"' && ! lsmod | grep -q rds) || (! modinfo rds &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 13 'Verifique se o módulo do kernel do TIPC não está disponível' 'Média' '(modinfo tipc &>/dev/null && modprobe --showconfig | grep -Pq '"'"'\b(install|blacklist)\h+tipc\b'"'"' && ! lsmod | grep -q tipc) || (! modinfo tipc &>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 14 'Verifique se core dumps estão restritos' 'Média' '(sysctl -n fs.suid_dumpable 2>/dev/null | grep -q '"'"'^0$'"'"') && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 15 'Verifique se ptrace_scope está restrito' 'Média' '(sysctl -n kernel.yama.ptrace_scope | grep -q '"'"'^[1-3]$'"'"') && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 16 'Verifique se NX/XD está ativo' Alta '(grep -q '"'"'nx'"'"' /proc/cpuinfo && dmesg | grep -qi '"'"'NX.*active'"'"') && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 17 'Verifique se ASLR está habilitado' Alta '(sysctl -n kernel.randomize_va_space | grep -q '"'"'^2$'"'"') && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 18 'Verifique se IOMMU está ativo' Alta '(grep -q '"'"'iommu=on'"'"' /proc/cmdline) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 21 'Verifique se user namespace está desabilitado' 'Média' '( [ ! -e /proc/sys/kernel/unprivileged_userns_clone ] || sysctl -n kernel.unprivileged_userns_clone 2>/dev/null | grep -q '"'"'^0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 22 'Verifique se protected_symlinks está habilitado' 'Média' '(sysctl -n fs.protected_symlinks | grep -q '"'"'^1$'"'"') && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 24 'Verifique se suid_dumpable=0' 'Média' '(sysctl -n fs.suid_dumpable | grep -q '"'"'^0$'"'"') && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 44 'Sticky bit em diretórios world-writable' 'Média' '(find / -xdev -type d -perm -0002 ! -perm -1000 2>/dev/null | grep . && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 45 'Sticky bit em /tmp' Baixa '(stat -c "%A" /tmp | grep -q '"'"'t'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 46 'Sticky bit em /var/tmp' Baixa '(stat -c "%A" /var/tmp | grep -q '"'"'t'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
