run_item 50 'Permissões seguras no arquivo do bootloader' Alta '(stat -Lc '"'"'%a %U %G'"'"' /boot/grub2/grub.cfg 2>/dev/null | grep -Eq '"'"'^(400|600) root root$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 51 'Single user mode com autenticação' 'Média' '(grep -q '"'"'^ExecStart=-/bin/sh'"'"' /usr/lib/systemd/system/emergency.service && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 56 'Prelink removido' Baixa '(rpm -q prelink &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 57 'xinetd removido' 'Média' '(rpm -q xinetd &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 58 'Sincronização de tempo em uso' 'Média' '( systemctl is-active --quiet chronyd &>/dev/null || systemctl is-active --quiet ntpd &>/dev/null || systemctl is-active --quiet systemd-timesyncd &>/dev/null ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 73 'NIS server ausente' Alta '(rpm -q ypserv &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 74 'Telnet server ausente' Alta '(rpm -q telnet-server &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 75 'MTA em modo local-only' 'Média' '( [ ! -f /etc/postfix/main.cf ] || grep -Eq '"'"'^[[:space:]]*inet_interfaces[[:space:]]*=[[:space:]]*(localhost|loopback-only)\b'"'"' /etc/postfix/main.cf 2>/dev/null ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 79 'Cliente NIS ausente' 'Média' '(rpm -q ypbind &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 80 'Cliente rsh ausente' Alta '(rpm -q rsh &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 81 'Cliente talk ausente' Baixa '(rpm -q talk &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 82 'Cliente telnet ausente' 'Média' '(rpm -q telnet &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 85 'TFTP server removido' Alta '(rpm -q tftp-server &>/dev/null && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 86 'PolicyKit endurecido' Alta '( grep -Ehv '"'"'^[[:space:]]*(//|#)'"'"' /etc/polkit-1/rules.d/*.rules 2>/dev/null | grep -Eq '"'"'polkit\.Result\.YES|[^[:alnum:]_]allow[^[:alnum:]_]'"'"' ) && echo "FAIL" || echo "PASS"' '(?i)^\s*PASS\s*$'
run_item 87 'Assinaturas de pacotes habilitadas' 'Média' '( grep -Eq '"'"'^[[:space:]]*gpgcheck[[:space:]]*=[[:space:]]*1'"'"' /etc/dnf/dnf.conf /etc/yum.conf 2>/dev/null && ! grep -ERq '"'"'^[[:space:]]*(gpgcheck|localpkg_gpgcheck)[[:space:]]*=[[:space:]]*0'"'"' /etc/dnf/dnf.conf /etc/yum.conf /etc/yum.repos.d 2>/dev/null ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 89 'Apenas um daemon de time sync' 'Média' '( ( systemctl is-active --quiet chronyd &>/dev/null && ! systemctl is-active --quiet ntpd &>/dev/null && ! systemctl is-active --quiet systemd-timesyncd &>/dev/null ) || ( ! systemctl is-active --quiet chronyd &>/dev/null && systemctl is-active --quiet ntpd &>/dev/null && ! systemctl is-active --quiet systemd-timesyncd &>/dev/null ) || ( ! systemctl is-active --quiet chronyd &>/dev/null && ! systemctl is-active --quiet ntpd &>/dev/null && systemctl is-active --quiet systemd-timesyncd &>/dev/null ) ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 90 'Cron/at seguros e restritos' Alta '(stat -Lc '"'"'%a %U %G'"'"' /etc/cron.allow 2>/dev/null | grep -Eq '"'"'^640 root (root|crontab)$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 92 'Redirecionamentos de pacotes desabilitados' Alta '(sysctl -n net.ipv4.conf.all.send_redirects 2>/dev/null | grep -q '"'"'^0$'"'"' && sysctl -n net.ipv4.conf.default.send_redirects 2>/dev/null | grep -q '"'"'^0$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
