run_item 94 'ICMP redirects bloqueados' Alta '(sysctl -n net.ipv4.conf.all.accept_redirects 2>/dev/null | grep -q '"'"'^0$'"'"' && sysctl -n net.ipv4.conf.default.accept_redirects 2>/dev/null | grep -q '"'"'^0$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 96 'ICMP broadcast ignorado' Baixa '(sysctl -n net.ipv4.icmp_echo_ignore_broadcasts 2>/dev/null | grep -q '"'"'^1$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 97 'Respostas ICMP inválidas ignoradas' Baixa '(sysctl -n net.ipv4.icmp_ignore_bogus_error_responses 2>/dev/null | grep -q '"'"'^1$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 98 'TCP SYN cookies habilitados' Alta '(sysctl -n net.ipv4.tcp_syncookies 2>/dev/null | grep -q '"'"'^1$'"'"' && echo "PASS" || echo "FAIL")' '(?i)^\s*PASS\s*$'
run_item 102 'Wireless/Bluetooth desabilitados' 'Média' '(lsmod | grep -Eq '"'"'bluetooth|iwlwifi'"'"' && echo "FAIL" || echo "PASS")' '(?i)^\s*PASS\s*$'
run_item 109 'Permissões seguras em sshd_config e chaves' Alta '( stat -c %a /etc/ssh/sshd_config | grep -Eq '"'"'^(600|400)$'"'"' && [ "$(stat -c %U:%G /etc/ssh)" = "root:root" ] && ! find /etc/ssh -maxdepth 1 -type f -name '"'"'ssh_host_*_key'"'"' ! -perm 0600 -print -quit 2>/dev/null | grep -q . ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
