run_item 114 'IgnoreRhosts habilitado' Alta '(grep -Eq '"'"'^[[:space:]]*IgnoreRhosts[[:space:]]+yes'"'"' /etc/ssh/sshd_config) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
