run_item 132 'pam_faillock habilitado' Alta '(grep -Eq '"'"'pam_faillock\.so'"'"' /etc/pam.d/system-auth /etc/pam.d/password-auth 2>/dev/null) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 133 'pam_tally2 NÃO deve existir em RHEL 8/9' Alta '! grep -Eq '"'"'pam_tally2\.so'"'"' /etc/pam.d/*auth && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
