run_item 135 'minlen ≥ 14' Alta 'shopt -s nullglob; files=(/etc/security/pwquality.conf /etc/security/pwquality.conf.d/*.conf); grep -Psiq '"'"'^\s*minlen\s*=\s*(1[4-9]|[2-9][0-9]+)'"'"' "${files[@]}" && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
