run_item 167 'Tamanho de armazenamento de audit log' 'Média' '( grep -Eq '"'"'^\s*max_log_file\s*=\s*[1-9]'"'"' /etc/audit/auditd.conf ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 169 'Auditoria de alterações em data/hora' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'adjtimex|settimeofday|clock_settime'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 170 'Auditoria de alterações em contas/grupos' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'/etc/(passwd|shadow|group|gshadow)'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 171 'Auditoria de alterações no ambiente de rede' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'sethostname|setdomainname|/etc/hosts|/etc/hostname'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 173 'Auditoria de login/logout' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'/var/log/faillog|/var/log/lastlog|/var/run/utmp'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 174 'Auditoria de permissões DAC' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'chmod|chown|fchmod|fchown'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 175 'Auditoria de acessos não autorizados' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'EACCES|EPERM'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 177 'Auditoria de mount/unmount' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'mount|umount'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 178 'Auditoria de deleção de arquivos' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'unlink|rename|rmdir|unlinkat|renameat'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 179 'Auditoria de kernel modules' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'init_module|finit_module|delete_module'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 180 'Auditoria de sudoers/logs de sudo' 'Média' '( auditctl -l 2>/dev/null | grep -Eq '"'"'/etc/sudoers|/etc/sudoers.d'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 185 'Verificar permissões de /etc/passwd' 'Média' '( [ -f /etc/passwd ] && stat -Lc "%a %u %g" /etc/passwd | grep -Eq '"'"'^64[0-9] 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 186 'Verificar permissões de /etc/passwd-' 'Média' '( [ -f /etc/passwd- ] && stat -Lc "%a %u %g" /etc/passwd- | grep -Eq '"'"'^64[0-9] 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 187 'Verificar permissões de /etc/shadow' 'Média' '( [ -f /etc/shadow ] && stat -Lc "%a %u %g" /etc/shadow | grep -Eq '"'"'^0+ 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
