run_item 189 'Verificar permissões de /etc/gshadow-' Alta '( [ -f /etc/gshadow- ] && stat -Lc "%a %u %g" /etc/gshadow- | grep -Eq '"'"'^(0+|600|60[0-9]|[0-5][0-9]{2}) 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 190 'Verificar permissões de /etc/gshadow' Alta '( [ -f /etc/gshadow ] && stat -Lc "%a %u %g" /etc/gshadow | grep -Eq '"'"'^(0+|600|60[0-9]|[0-5][0-9]{2}) 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 191 'Verificar permissões de /etc/group' 'Média' '( [ -f /etc/group ] && stat -Lc "%a %u %g" /etc/group | grep -Eq '"'"'^64[0-9] 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 192 'Verificar permissões de /etc/group-' 'Média' '( [ -f /etc/group- ] && stat -Lc "%a %u %g" /etc/group- | grep -Eq '"'"'^64[0-9] 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 194 'Verificar permissões de /etc/security/opasswd' Alta '( [ -f /etc/security/opasswd ] && stat -Lc "%a %u %g" /etc/security/opasswd | grep -Eq '"'"'^600 0 0$'"'"' ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 195 'Verificar existência de arquivos órfãos (UID/GID sem dono)' Baixa '( find / -xdev \( -nouser -o -nogroup \) 2>/dev/null | grep -q . ) && echo "FAIL" || echo "PASS"' '(?i)^\s*PASS\s*$'
run_item 196 'Verificar world-writable fora de áreas permitidas' 'Média' '( find / -xdev \( -type f -o -type d \) -not -path "/tmp/*" -not -path "/var/tmp/*" -not -path "/dev/shm/*" -perm -0002 2>/dev/null | grep -q . ) && echo "FAIL" || echo "PASS"' '(?i)^\s*PASS\s*$'
run_item 197 'Verificar arquivos/diretórios sem owner ou group' 'Média' '( find / -xdev \( -nouser -o -nogroup \) 2>/dev/null | grep -q . ) && echo "FAIL" || echo "PASS"' '(?i)^\s*PASS\s*$'
run_item 199 'Verificar se usuários possuem diretório home válido)' Baixa '( awk -F: '"'"'$3>=1000 && $1!="nfsnobody"{print $6}'"'"' /etc/passwd | while read -r h; do [ -d "$h" ] || exit 1; done ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 200 'Verificar ownership das homes dos usuários' 'Média' '( awk -F: '"'"'$3>=1000 && $1!="nfsnobody"{print $1,$6}'"'"' /etc/passwd | while read -r u h; do [ -d "$h" ] && [ "$(stat -Lc %U "$h")" = "$u" ] || exit 1; done ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 201 'Verificar permissões das homes (<=750)' 'Média' '( awk -F: '"'"'$3>=1000 && $1!="nfsnobody"{print $6}'"'"' /etc/passwd | while read -r h; do [ -d "$h" ] && [ "$(stat -Lc %a "$h")" -le 750 ] || exit 1; done ) && echo "PASS" || echo "FAIL"' '(?i)^\s*PASS\s*$'
run_item 202 'Verificar dotfiles inseguros nas homes' Baixa '( while read -r h; do [ -d "$h" ] || continue; find "$h" -maxdepth 1 -type f -name ".*" -perm /022 2>/dev/null; done < <(awk -F: '"'"'$3>=1000 && $1!="nfsnobody"{print $6}'"'"' /etc/passwd) | grep -q . ) && echo "FAIL" || echo "PASS"' '(?i)^\s*PASS\s*$'
run_item 203 'Verificar arquivos .forward/.netrc/.rhosts nas homes' 'Média' '( while read -r h; do [ -d "$h" ] || continue; for f in "$h/.forward" "$h/.netrc" "$h/.rhosts"; do [ -e "$f" ] && echo "$f"; done; done < <(awk -F: '"'"'$3>=1000 && $1!="nfsnobody"{print $6}'"'"' /etc/passwd) | grep -q . ) && echo "FAIL" || echo "PASS"' '(?i)^\s*PASS\s*$'
